/* Generated by scripts/build-pwa.mjs. Only verified static resources enter this cache. */
'use strict';
const VERSION = 'BUILD_VERSION';
const ENTRIES = /* BUILD_ENTRIES */ {};
const BASE = new URL(self.registration.scope);
const PREFIX = 'lifeos-shell-v1:' + BASE.pathname + ':';
const CACHE = PREFIX + VERSION;
const ASSETS = new Map(Object.entries(ENTRIES).map(([file,hash])=>[new URL(file,BASE).href,{file,hash}]));
const hex = bytes => [...new Uint8Array(bytes)].map(n=>n.toString(16).padStart(2,'0')).join('');

async function verified(url, hash) {
  const response = await fetch(new Request(url,{cache:'no-cache',credentials:'same-origin',redirect:'error'}));
  if (response.status !== 200 || response.type === 'opaque' || response.redirected || response.url !== url) throw new Error('Static resource unavailable');
  const bytes = await response.arrayBuffer();
  if (hex(await crypto.subtle.digest('SHA-256',bytes)) !== hash) throw new Error('Static resource digest mismatch');
  // Cache only source bytes and content type, never platform authentication/cookie headers.
  return new Response(bytes,{status:200,headers:{'Content-Type':response.headers.get('Content-Type')||'application/octet-stream','X-LifeOS-Shell':VERSION}});
}
self.addEventListener('install',event=>event.waitUntil((async()=>{
  const cache = await caches.open(CACHE);
  // No skipWaiting. Partial downloads cannot activate a mixed version.
  for (const [url,entry] of ASSETS) {
    const previous = await cache.match(url);
    if (!previous) await cache.put(url,await verified(url,entry.hash));
  }
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
  // Exact scope namespace and version pattern only. Other caches/stores are untouched.
  for (const name of await caches.keys()) {
    const suffix=name.startsWith(PREFIX)?name.slice(PREFIX.length):'';
    if (name!==CACHE && /^\d{4}\.\d{2}\.\d{2}-[a-f0-9]{16}$/.test(suffix)) await caches.delete(name);
  }
  // No clients.claim: existing uncontrolled forms keep their original document lifecycle.
})()));
self.addEventListener('fetch',event=>{
  const request=event.request, url=new URL(request.url);
  url.hash=''; // Navigation requests can retain the SPA fragment in Request.url.
  if (request.method!=='GET'||url.origin!==BASE.origin||url.search||request.headers.has('Range')) return;
  const isShell=request.mode==='navigate'&&(url.href===BASE.href||url.href===new URL('index.html',BASE).href);
  const key=isShell?new URL('index.html',BASE).href:url.href;
  // Notion's explicit no-store capability probe must reach the actual server.
  if ((!isShell&&request.cache==='no-store')||!ASSETS.has(key)) return;
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE), cached=await cache.match(key);
    if (cached) return cached;
    try {const response=await verified(key,ASSETS.get(key).hash);await cache.put(key,response.clone());return response;}
    catch (error) {return new Response('Life OS 基础资源不可用。请联网后重新打开；本机记录未被清除。',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}});}
  })());
});
self.addEventListener('message',event=>{
  if (event.data?.type==='LIFEOS_PWA_INFO' && event.ports[0]) event.ports[0].postMessage({type:'LIFEOS_PWA_INFO',version:VERSION});
});
